/* Checked metadata/projections; no computation, source evaluator or model call. */
#include "apx_frontend.h"
#include "apx_hash.h"
#include <string.h>
#include <inttypes.h>
#include <stdio.h>
static void quoted(ApxBuffer *b,const char *s){apx_json_quote(b,s,strlen(s));}
static void type_string(ApxBuffer *b,ApxType *t){ApxBuffer type;apx_buf_init(&type,b->ctx);apx_type_text(&type,t);apx_json_quote(b,type.data,type.length);}
static void begin(ApxBuffer *b,ApxProgram *p,const char *schema){apx_buf_put(b,"{\"schema\":");quoted(b,schema);apx_buf_put(b,",\"status\":\"ok\",\"language\":\"apodexis\",\"version\":\""APX_LANGUAGE_VERSION"\",\"source_hash\":");quoted(b,p->source_hash);}
static void fields_fact(ApxBuffer *b,ApxField *fields){apx_buf_put(b,"[");for(ApxField *f=fields;f;f=f->next){if(f!=fields)apx_buf_put(b,",");apx_buf_put(b,"{\"name\":");quoted(b,f->name);apx_buf_put(b,",\"type\":");type_string(b,f->type);apx_buf_put(b,"}");}apx_buf_put(b,"]");}
static void function_fact(ApxBuffer *b,ApxFunction *f){if(!f){apx_buf_put(b,"null");return;}apx_buf_put(b,"{\"name\":");quoted(b,f->name);apx_buf_put(b,",\"params\":");fields_fact(b,f->params);apx_buf_put(b,",\"return_type\":");type_string(b,f->returns);apx_buf_put(b,"}");}
static char *explain(ApxContext *ctx,ApxProgram *p){ApxBuffer b;unsigned nt=0,nf=0,nx=0;apx_buf_init(&b,ctx);begin(&b,p,"apodexis.explain_response.v1");apx_buf_put(&b,",\"module\":");quoted(&b,p->module);apx_buf_put(&b,",\"entrypoint\":");function_fact(&b,apx_find_function(p,"main"));apx_buf_put(&b,",\"types\":[");
    for(ApxDecl *d=p->types;d;d=d->next){if(nt++)apx_buf_put(&b,",");apx_buf_put(&b,"{\"kind\":");quoted(&b,d->is_enum?"enum":"struct");apx_buf_put(&b,",\"name\":");quoted(&b,d->name);apx_buf_put(&b,",\"fields\":");fields_fact(&b,d->fields);apx_buf_put(&b,",\"variants\":[");for(ApxVariant *v=d->variants;v;v=v->next){if(v!=d->variants)apx_buf_put(&b,",");apx_buf_put(&b,"{\"name\":");quoted(&b,v->name);apx_buf_put(&b,",\"fields\":");fields_fact(&b,v->fields);apx_buf_put(&b,"}");}apx_buf_put(&b,"]}");}
    apx_buf_put(&b,"],\"functions\":[");for(ApxFunction *f=p->functions;f;f=f->next){if(nf++)apx_buf_put(&b,",");function_fact(&b,f);}apx_buf_put(&b,"],\"tests\":[");for(ApxFunction *f=p->tests;f;f=f->next){if(nx++)apx_buf_put(&b,",");apx_buf_put(&b,"{\"name\":");quoted(&b,f->name);apx_buf_put(&b,"}");}
    apx_buf_printf(&b,"],\"compile_facts\":{\"canonical_source_bytes\":%zu,\"type_count\":%u,\"function_count\":%u,\"test_count\":%u}}",strlen(p->canonical),nt,nf,nx);return b.data;
}
static void contract_type(ApxBuffer *b,ApxType *t){static const char *names[]={"i64","f64","bool","str","array","option","result","builder","named","map"};apx_buf_put(b,"{\"kind\":");quoted(b,names[t->kind]);
    if(t->kind==APX_NAMED){apx_buf_put(b,",\"name\":");quoted(b,t->name);}
    else if(t->a){apx_buf_put(b,t->kind==APX_OPTION?",\"item\":" : t->kind==APX_RESULT?",\"ok\":" : t->kind==APX_MAP?",\"values\":" : ",\"items\":");contract_type(b,t->a);if(t->b){apx_buf_put(b,",\"error\":");contract_type(b,t->b);}}
    apx_buf_put(b,"}");
}
static void contract_fields(ApxBuffer *b,ApxField *fields){apx_buf_put(b,"[");for(ApxField *f=fields;f;f=f->next){if(f!=fields)apx_buf_put(b,",");apx_buf_put(b,"{\"name\":");quoted(b,f->name);apx_buf_put(b,",\"type\":");contract_type(b,f->type);apx_buf_put(b,"}");}apx_buf_put(b,"]");}
static int declaration_before(ApxDecl *a,ApxDecl *b){return strcmp(a->name,b->name)<0;}
static void mark_named(ApxProgram *p,ApxType *t,unsigned depth){if(depth>APX_MAX_DEPTH)return;if(t->kind==APX_NAMED){ApxDecl *d=apx_find_decl(p,t->name);if(d&&!d->visit){d->visit=1;for(ApxField *f=d->fields;f;f=f->next)mark_named(p,f->type,depth+1);for(ApxVariant *v=d->variants;v;v=v->next)for(ApxField *f=v->fields;f;f=f->next)mark_named(p,f->type,depth+1);}}else{if(t->a)mark_named(p,t->a,depth+1);if(t->b)mark_named(p,t->b,depth+1);}}
static char *contract(ApxContext *ctx,ApxProgram *p){ApxFunction *main=apx_find_function(p,"main");if(!main)apx_fail(ctx,"N101","resolve","unknown_symbol",(ApxSpan){0,0},"main function not found");ApxBuffer value,b;apx_buf_init(&value,ctx);apx_buf_put(&value,"{\"name\":\"main\",\"parameters\":");contract_fields(&value,main->params);apx_buf_put(&value,",\"return_type\":");contract_type(&value,main->returns);apx_buf_put(&value,",\"definitions\":[");
    for(ApxDecl *d=p->types;d;d=d->next)d->visit=0;
    for(ApxField *f=main->params;f;f=f->next)mark_named(p,f->type,0);
    mark_named(p,main->returns,0);int first=1;
    for(;;){ApxDecl *next=NULL;for(ApxDecl *d=p->types;d;d=d->next)if(d->visit==1&&(!next||declaration_before(d,next)))next=d;if(!next)break;next->visit=2;if(!first)apx_buf_put(&value,",");first=0;apx_buf_put(&value,"{\"kind\":");quoted(&value,next->is_enum?"enum":"struct");apx_buf_put(&value,",\"name\":");quoted(&value,next->name);if(!next->is_enum){apx_buf_put(&value,",\"fields\":");contract_fields(&value,next->fields);}else{apx_buf_put(&value,",\"variants\":[");for(ApxVariant *v=next->variants;v;v=v->next){if(v!=next->variants)apx_buf_put(&value,",");apx_buf_put(&value,"{\"name\":");quoted(&value,v->name);apx_buf_put(&value,",\"fields\":");contract_fields(&value,v->fields);apx_buf_put(&value,"}");}apx_buf_put(&value,"]");}apx_buf_put(&value,"}");}
    apx_buf_put(&value,"]}");char hash[71]="apxc1:";apx_sha256(value.data,value.length,hash+6);apx_buf_init(&b,ctx);begin(&b,p,"apodexis.entrypoint_contract_response.v1");apx_buf_put(&b,",\"contract_hash\":");quoted(&b,hash);apx_buf_put(&b,",\"contract\":");apx_buf_bytes(&b,value.data,value.length);apx_buf_put(&b,"}");return b.data;
}
/* Human-readable checked AST projection, with stable structural byte mappings. */
static void expression(ApxBuffer *b,ApxExpr *e){
    switch(e->kind){case APX_INT_EXPR:apx_buf_printf(b,"%"PRId64,e->integer);return;case APX_FLOAT_EXPR:apx_buf_printf(b,"%.17g",e->real);return;case APX_BOOL_EXPR:apx_buf_put(b,e->integer?"true":"false");return;case APX_STRING_EXPR:apx_json_quote(b,e->text,e->length);return;case APX_VAR_EXPR:apx_buf_put(b,e->text);return;case APX_TYPE_EXPR:apx_type_text(b,e->marker);return;default:break;}
    if(e->kind==APX_ARRAY_EXPR){apx_buf_put(b,"[");for(ApxArg *a=e->args;a;a=a->next){if(a!=e->args)apx_buf_put(b,", ");expression(b,a->expr);}apx_buf_put(b,"]");return;}
    if(e->opcode>=1&&e->opcode<=11&&e->args&&e->args->next){apx_buf_put(b,"(");expression(b,e->args->expr);apx_buf_printf(b," %s ",e->text);expression(b,e->args->next->expr);apx_buf_put(b,")");return;}
    if(e->opcode==18){expression(b,e->args->expr);apx_buf_put(b,".");apx_buf_put(b,e->args->next->expr->text);return;}
    apx_buf_put(b,e->text);apx_buf_put(b,"(");for(ApxArg *a=e->args;a;a=a->next){if(a!=e->args)apx_buf_put(b,", ");if(a->name){apx_buf_printf(b,"%s=",a->name);}expression(b,a->expr);}apx_buf_put(b,")");
}
static void pad(ApxBuffer *b,unsigned n){while(n--)apx_buf_put(b,"  ");}
static void node(ApxBuffer *nodes,const char *handle,const char *kind,size_t start,size_t end){if(nodes->length>1)apx_buf_put(nodes,",");apx_buf_put(nodes,"{\"handle\":");quoted(nodes,handle);apx_buf_put(nodes,",\"kind\":");quoted(nodes,kind);apx_buf_printf(nodes,",\"start_byte\":%zu,\"end_byte\":%zu}",start,end);}
static void statements(ApxBuffer *b,ApxBuffer *nodes,ApxStmt *body,unsigned depth,const char *prefix){unsigned index=0;for(ApxStmt *s=body;s;s=s->next,index++){ApxBuffer path;apx_buf_init(&path,b->ctx);apx_buf_printf(&path,"%s/%u",prefix,index);size_t start=b->length;pad(b,depth);const char *kind="statement";
    switch(s->kind){case 'L':kind="let";apx_buf_printf(b,"let %s: ",s->name);apx_type_text(b,s->expr->type);apx_buf_put(b," = ");expression(b,s->expr);break;case 'S':kind="set";apx_buf_printf(b,"set %s = ",s->name);expression(b,s->expr);break;case 'R':kind="return";apx_buf_put(b,"return ");expression(b,s->expr);break;case 'A':kind="assert";apx_buf_put(b,"assert ");expression(b,s->expr);break;case 'Z':kind="trap";apx_buf_put(b,"trap ");expression(b,s->expr);break;case '?':kind="if";apx_buf_put(b,"if ");expression(b,s->expr);apx_buf_put(b,":");break;case 'W':kind="while";apx_buf_put(b,"while ");expression(b,s->expr);apx_buf_put(b,":");break;case 'E':kind="each";apx_buf_printf(b,"each %s in ",s->name);expression(b,s->expr);apx_buf_put(b,":");break;case 'C':kind="case";apx_buf_put(b,"match ");expression(b,s->expr);apx_buf_put(b,":");break;default:break;}
    apx_buf_put(b,"\n");node(nodes,path.data,kind,start,b->length);if(s->body)statements(b,nodes,s->body,depth+1,path.data);
    unsigned armindex=0;for(ApxArm *a=s->arms;a;a=a->next,armindex++){ApxBuffer arm;apx_buf_init(&arm,b->ctx);apx_buf_printf(&arm,"%s/arm/%u",path.data,armindex);size_t armstart=b->length;pad(b,depth+1);apx_buf_put(b,a->name);for(ApxField *f=a->bindings;f;f=f->next)apx_buf_printf(b," %s",f->name);apx_buf_put(b,":\n");node(nodes,arm.data,"arm",armstart,b->length);statements(b,nodes,a->body,depth+2,arm.data);}
}}
static char *pseudocode(ApxContext *ctx,ApxProgram *p){ApxBuffer b,nodes,out;apx_buf_init(&b,ctx);apx_buf_init(&nodes,ctx);apx_buf_put(&nodes,"[");apx_buf_printf(&b,"module %s\n",p->module);node(&nodes,"module","module",0,b.length);
    for(ApxDecl *d=p->types;d;d=d->next){size_t start=b.length;apx_buf_printf(&b,"\n%s %s:\n",d->is_enum?"enum":"struct",d->name);for(ApxField *f=d->fields;f;f=f->next){pad(&b,1);apx_buf_printf(&b,"%s: ",f->name);apx_type_text(&b,f->type);apx_buf_put(&b,"\n");}for(ApxVariant *v=d->variants;v;v=v->next){pad(&b,1);apx_buf_put(&b,v->name);for(ApxField *f=v->fields;f;f=f->next){apx_buf_printf(&b," %s: ",f->name);apx_type_text(&b,f->type);}apx_buf_put(&b,"\n");}ApxBuffer handle;apx_buf_init(&handle,ctx);apx_buf_printf(&handle,"type/%s",d->name);node(&nodes,handle.data,"type",start,b.length);}
    for(unsigned tests=0;tests<2;tests++)for(ApxFunction *f=tests?p->tests:p->functions;f;f=f->next){ApxBuffer handle;apx_buf_init(&handle,ctx);apx_buf_printf(&handle,"%s/%s",tests?"test":"function",f->name);size_t start=b.length;apx_buf_printf(&b,"\n%s %s",tests?"test":"function",f->name);if(!tests){apx_buf_put(&b,"(");for(ApxField *a=f->params;a;a=a->next){if(a!=f->params)apx_buf_put(&b,", ");apx_buf_printf(&b,"%s: ",a->name);apx_type_text(&b,a->type);}apx_buf_put(&b,") -> ");apx_type_text(&b,f->returns);}apx_buf_put(&b,":\n");node(&nodes,handle.data,tests?"test":"function",start,b.length);statements(&b,&nodes,f->body,1,handle.data);}
    apx_buf_put(&nodes,"]");char hash[71]="apxp1:";apx_sha256(b.data,b.length,hash+6);apx_buf_init(&out,ctx);begin(&out,p,"apodexis.pseudocode_response.v1");apx_buf_put(&out,",\"renderer\":\"apodexis.pseudocode.qbe.v1\",\"pseudocode_hash\":");quoted(&out,hash);apx_buf_put(&out,",\"text\":");apx_json_quote(&out,b.data,b.length);apx_buf_put(&out,",\"nodes\":");apx_buf_bytes(&out,nodes.data,nodes.length);apx_buf_put(&out,"}");return out.data;
}
void apx_metadata_render(ApxContext *ctx,ApxProgram *p,char **e,char **c,char **pseudo){if(e)*e=explain(ctx,p);if(c)*c=contract(ctx,p);if(pseudo)*pseudo=pseudocode(ctx,p);}
